package app.kinnect.live;
import android.app.Activity;import android.graphics.Color;import android.util.TypedValue;import android.view.*;import android.widget.*;import org.json.JSONObject;
/** One compact balance layout shared by Wallet and Shop. */
final class CoinBalanceCard extends LinearLayout {
 static android.graphics.drawable.Drawable coin(Activity a,int size){int id=a.getResources().getIdentifier("ic_web_coins","drawable",a.getPackageName());android.graphics.drawable.Drawable d=a.getDrawable(id).mutate();d.setBounds(0,0,size,size);return d;}
 static String display(long value){java.text.NumberFormat f=java.text.NumberFormat.getInstance(new java.util.Locale("vi","VN"));if(value>999999999L){f.setMaximumFractionDigits(2);return f.format(value/1000000000.0)+(I18n.current().equals("en")?" B":" tỷ");}return f.format(value);}
 private static FrameLayout coinHalo(Activity a,int coinDp,CommerceUi ui){int coinPx=ui.dp(coinDp),padPx=ui.dp(3),boxPx=coinPx+padPx*2;FrameLayout halo=new FrameLayout(a);android.graphics.drawable.GradientDrawable circle=new android.graphics.drawable.GradientDrawable();circle.setShape(android.graphics.drawable.GradientDrawable.OVAL);circle.setColor(0xff2d165e);halo.setBackground(circle);ImageView img=new ImageView(a);img.setImageDrawable(coin(a,coinPx));img.setScaleType(ImageView.ScaleType.FIT_CENTER);halo.addView(img,new FrameLayout.LayoutParams(coinPx,coinPx,Gravity.CENTER));halo.setLayoutParams(new LinearLayout.LayoutParams(boxPx,boxPx));return halo;}
 CoinBalanceCard(Activity a,JSONObject data,boolean compact,boolean hidden,Runnable toggle){super(a);CommerceUi ui=new CommerceUi(a);setOrientation(VERTICAL);setPadding(ui.dp(16),ui.dp(compact?12:14),ui.dp(16),ui.dp(compact?12:14));android.graphics.drawable.GradientDrawable bg=new android.graphics.drawable.GradientDrawable(android.graphics.drawable.GradientDrawable.Orientation.TL_BR,WebDesign.WALLET_HERO_GRADIENT);bg.setCornerRadius(ui.dp(18));setBackground(bg);setTag(compact?"store:balance":"wallet:balance");LinearLayout top=ui.row();TextView title=ui.text(compact?"Số dư":"Tổng số dư xu",12,0xfff2edff,true);top.addView(title,new LinearLayout.LayoutParams(0,-2,1));if(toggle!=null){FrameLayout eye=ui.icon(hidden?"eye_off":"eye","Ẩn / hiện số dư",toggle);eye.setBackgroundColor(Color.TRANSPARENT);((ImageView)eye.getChildAt(0)).setColorFilter(Color.WHITE);int raw48=ui.dpRaw(48);top.addView(eye,new LinearLayout.LayoutParams(raw48,raw48));UiMetrics.enforceMinTouchTarget(eye);}addView(top);if(!compact){long totalCoins=data.optLong("purchasedCoins")+data.optLong("giftedCoins",data.optLong("trialCoins"));LinearLayout totalRow=ui.row();totalRow.setPadding(0,ui.dp(2),0,ui.dp(10));FrameLayout totalHalo=coinHalo(a,24,ui);LinearLayout.LayoutParams thp=(LinearLayout.LayoutParams)totalHalo.getLayoutParams();thp.rightMargin=ui.dp(8);totalRow.addView(totalHalo,thp);TextView total=ui.text(hidden?"••••":display(totalCoins)+" "+I18n.t("xu"),28,Color.WHITE,true);total.setSingleLine(true);total.setHorizontallyScrolling(false);total.setAutoSizeTextTypeUniformWithConfiguration(16,28,1,TypedValue.COMPLEX_UNIT_SP);total.setGravity(Gravity.CENTER_VERTICAL);total.setTag("wallet:total");total.setContentDescription(I18n.t("Tổng số dư xu")+" · "+totalCoins);totalRow.addView(total,new LinearLayout.LayoutParams(0,-2,1));addView(totalRow,new LinearLayout.LayoutParams(-1,-2));View sep=new View(a);sep.setBackgroundColor(0x33ffffff);addView(sep,new LinearLayout.LayoutParams(-1,Math.max(1,ui.dp(1))));}{LinearLayout row=ui.row();row.setGravity(Gravity.TOP);for(int i=0;i<2;i++){boolean paid=i==0;LinearLayout cell=ui.col();cell.setPadding(paid?0:ui.dp(12),ui.dp(compact?8:10),paid?ui.dp(12):0,0);TextView label=ui.text(paid?"Xu mua":"Xu tặng",11,0xfff2edff,false);if(paid){LinearLayout labelRow=ui.row();labelRow.setMinimumHeight(ui.dp(28));FrameLayout labelHalo=coinHalo(a,16,ui);LinearLayout.LayoutParams lhp=(LinearLayout.LayoutParams)labelHalo.getLayoutParams();lhp.rightMargin=ui.dp(6);labelRow.addView(labelHalo,lhp);labelRow.addView(label);cell.addView(labelRow);}else{label.setCompoundDrawablesRelative(ui.glyph("gift",Color.WHITE,16),null,null,null);label.setCompoundDrawablePadding(ui.dp(6));label.setMinHeight(ui.dp(28));cell.addView(label);}long value=paid?data.optLong("purchasedCoins"):data.optLong("giftedCoins",data.optLong("trialCoins"));TextView amount=ui.text(hidden?"••••":display(value),20,Color.WHITE,true);amount.setSingleLine(true);amount.setHorizontallyScrolling(false);amount.setAutoSizeTextTypeUniformWithConfiguration(12,20,1,TypedValue.COMPLEX_UNIT_SP);amount.setMinHeight(ui.dp(34));amount.setTag(compact?"store:balance:"+(paid?"purchasedCoins":"trialCoins"):paid?"wallet:purchased":"wallet:coins");amount.setContentDescription(I18n.t(paid?"Xu mua":"Xu tặng")+" · "+value);cell.addView(amount,new LinearLayout.LayoutParams(-1,-2));row.addView(cell,new LinearLayout.LayoutParams(0,-2,1));if(i==0){View divider=new View(a);divider.setBackgroundColor(0x55ffffff);LinearLayout.LayoutParams at=new LinearLayout.LayoutParams(ui.dp(1),ui.dp(40));at.topMargin=ui.dp(8);row.addView(divider,at);}}addView(row);}}
}
